{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile, with the overall body, head and limbs of a brown bear combined with parts of a large beetle. It is covered in dense shaggy brown fur that is lighter on the muzzle and darker on the legs, stands on four thick bear legs with clawed paws, has a bear's head with a blunt snout and small rounded ears, and bears glossy dark reddish-brown beetle wing-covers on its neck, chest and side, two large translucent membranous insect wings with brown veining protruding from the sides of its torso, rows of narrow slit-like openings in the fur on its flank and hindquarter, and a segmented armored tail ending in a small fork.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with thick brown fur, elongated snout, black nose, small brown eyes, and a slightly open mouth",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry bear ears",
      "where": "on top of the head"
    },
    {
      "part": "legs",
      "looks_like": "four thick heavily furred brown bear legs",
      "where": "two front legs under the chest and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "large bear paws with long curved light-colored claws",
      "where": "at the ends of each of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "segmented glossy dark reddish-brown beetle abdomen with distinct rings and a two-pronged tip",
      "where": "extending from the rear of the body"
    },
    {
      "part": "wings",
      "looks_like": "two large translucent membranous insect wings with brown veins and slightly amber edges",
      "where": "one large wing protruding from the left side of the torso and one smaller wing protruding from the right side of the chest"
    },
    {
      "part": "plates",
      "looks_like": "several glossy dark reddish-brown hard beetle elytra, smooth and domed with a central seam on the largest one",
      "where": "covering the back of the neck, the shoulder, the lower chest, and the side of the torso where the wings attach"
    },
    {
      "part": "gills",
      "looks_like": "rows of narrow vertical slit-like openings in the fur, resembling spiracles",
      "where": "a row of about five slits on the mid-flank behind the front leg and a longer row of about nine slits on the hindquarter"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy brown fur with lighter tan on the muzzle and darker brown on the lower legs, no other distinct spots or stripes",
      "where": "covering the entire body except for the beetle plates, wings and tail"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0
}
